 */
public object FfiConverterTypeBknDbEngine: FfiConverter<BknDbEngine, Long> {
    override fun lower(value: BknDbEngine): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): BknDbEngine {
        return BknDbEngine(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): BknDbEngine {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: BknDbEngine) = 8UL

    override fun write(value: BknDbEngine, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



