sealed class FfiBknException: kotlin.Exception() {
    
    class Backend(
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class TableNotFound(
        
        val `table`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }"
    }
    
    class NotFound(
        ) : FfiBknException() {
        override val message
            get() = ""
    }
    
    class Encoding(
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class ReservedTableName(
        
        val `table`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiBknException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiBknException = FfiConverterTypeFfiBknError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiBknError : FfiConverterRustBuffer<FfiBknException> {
    override fun read(buf: ByteBuffer): FfiBknException {
        

        return when(buf.getInt()) {
            1 -> FfiBknException.Backend(
                FfiConverterString.read(buf),
                )
            2 -> FfiBknException.TableNotFound(
                FfiConverterString.read(buf),
                )
            3 -> FfiBknException.NotFound()
            4 -> FfiBknException.Encoding(
                FfiConverterString.read(buf),
                )
            5 -> FfiBknException.ReservedTableName(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiBknException): ULong {
        return when(value) {
            is FfiBknException.Backend -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiBknException.TableNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`table`)
            )
            is FfiBknException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiBknException.Encoding -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiBknException.ReservedTableName -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`table`)
            )
        }
    }

    override fun write(value: FfiBknException, buf: ByteBuffer) {
        when(value) {
            is FfiBknException.Backend -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiBknException.TableNotFound -> {
                buf.putInt(2)
                FfiConverterString.write(value.`table`, buf)
                Unit
            }
            is FfiBknException.NotFound -> {
                buf.putInt(3)
                Unit
            }
            is FfiBknException.Encoding -> {
                buf.putInt(4)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiBknException.ReservedTableName -> {
                buf.putInt(5)
                FfiConverterString.write(value.`table`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




