/**
 * @suppress
 */
public object FfiConverterTypeFfiPropValue : FfiConverterRustBuffer<FfiPropValue>{
    override fun read(buf: ByteBuffer): FfiPropValue {
        return when(buf.getInt()) {
            1 -> FfiPropValue.Null
            2 -> FfiPropValue.Str(
                FfiConverterString.read(buf),
                )
            3 -> FfiPropValue.Int(
                FfiConverterLong.read(buf),
                )
            4 -> FfiPropValue.Float(
                FfiConverterDouble.read(buf),
                )
            5 -> FfiPropValue.Bool(
                FfiConverterBoolean.read(buf),
                )
            6 -> FfiPropValue.Bytes(
                FfiConverterByteArray.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiPropValue): ULong = when(value) {
        is FfiPropValue.Null -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiPropValue.Str -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
        is FfiPropValue.Int -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.v1)
            )
        }
        is FfiPropValue.Float -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.v1)
            )
        }
        is FfiPropValue.Bool -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.v1)
            )
        }
        is FfiPropValue.Bytes -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: FfiPropValue, buf: ByteBuffer) {
        when(value) {
            is FfiPropValue.Null -> {
                buf.putInt(1)
                Unit
            }
            is FfiPropValue.Str -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiPropValue.Int -> {
                buf.putInt(3)
                FfiConverterLong.write(value.v1, buf)
                Unit
            }
            is FfiPropValue.Float -> {
                buf.putInt(4)
                FfiConverterDouble.write(value.v1, buf)
                Unit
            }
            is FfiPropValue.Bool -> {
                buf.putInt(5)
                FfiConverterBoolean.write(value.v1, buf)
                Unit
            }
            is FfiPropValue.Bytes -> {
                buf.putInt(6)
                FfiConverterByteArray.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






